    getCreditTransactions: {
        parameters: {
            query?: {
                limit?: number;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Recent transactions. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "success": true,
                     *       "transactions": [
                     *         {
                     *           "id": "6a1f3c9e2b7d4a0012ab3401",
                     *           "type": "topup",
                     *           "amountCents": 5000,
                     *           "amountFormatted": "+50.00 €",
                     *           "description": "Credit top-up",
                     *           "relatedResourceType": null,
                     *           "createdAt": "2026-09-28T10:00:00.000Z"
                     *         },
                     *         {
                     *           "id": "6a1f3c9e2b7d4a0012ab3402",
                     *           "type": "usage",
                     *           "amountCents": -60,
                     *           "amountFormatted": "-0.60 €",
                     *           "description": "Enrichment: phone + email",
                     *           "relatedResourceType": "SearchResult",
                     *           "createdAt": "2026-09-30T14:21:00.000Z"
                     *         },
                     *         {
                     *           "id": "6a1f3c9e2b7d4a0012ab3403",
                     *           "type": "refund",
                     *           "amountCents": 2,
                     *           "amountFormatted": "+0.02 €",
                     *           "description": "WhatsApp verification refund",
                     *           "relatedResourceType": "PhoneVerification",
                     *           "createdAt": "2026-10-01T09:12:00.000Z"
                     *         }
                     *       ]
                     *     }
                     */
                    "application/json": {
                        success?: boolean;
                        transactions?: {
                            id?: string;
                            /** @enum {string} */
                            type?: "topup" | "usage" | "refund" | "reversal";
                            amountCents?: number;
                            amountFormatted?: string;
                            description?: string;
                            /**
                             * @description Type of the billed resource. Stable key, prefer it over the `description` text to categorise a line.
                             * @enum {string|null}
                             */
                            relatedResourceType?: "SearchResult" | "Message" | "EnrichmentSession" | "CompanyEnrichmentSession" | "EmailVerification" | "PhoneVerification" | "AgentToolCall" | null;
                            /** Format: date-time */
                            createdAt?: string;
                        }[];
                    };
                };
            };
        };
    };
